	const wchar_t* TypeParserRuleName(vl::vint index)
	{
		static const wchar_t* results[] = {
			L"EnumItem",
			L"Enum",
			L"ClassPropType",
			L"classProp",
			L"ClassBody",
			L"Class",
			L"Type",
			L"File",
		};
		return results[index];
	}

